const {chromium}=require('C:/Users/User/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const assert=require('assert/strict');const fs=require('fs');const path=require('path');
(async()=>{
 const b=await chromium.launch({channel:'msedge',headless:true});
 const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();
 const errors=[];p.on('pageerror',e=>errors.push(e.message));const requested=[];p.on('request',r=>{if(r.url().includes('/_domain-preview/'))requested.push(r.url())});
 await p.goto('https://wordpress.alba-vision.ro/',{waitUntil:'networkidle'});
 await p.waitForFunction(()=>document.querySelectorAll('.domain-card').length>100);
 assert.equal(await p.locator('.domain-card img[src]').count(),0);assert.equal(requested.length,0);
 await p.fill('#search','black-robot.ro');
 let card=p.locator('.domain-card[data-domain="black-robot.ro"]');
 const name=card.locator('a.domain-name');assert.equal(await name.getAttribute('target'),'_blank');assert.equal(await name.getAttribute('href'),'https://black-robot.ro/');
 const popupPromise=p.waitForEvent('popup');await name.click();const popup=await popupPromise;
 assert.equal(await card.getAttribute('open'),null);await popup.close();
 assert.equal(await card.locator('.local-shortcut').getAttribute('target'),'_blank');
 await card.locator('.chevron').click();assert(await card.getAttribute('open')!==null);
 const previews=card.locator('.previews');await previews.scrollIntoViewIfNeeded();
 await p.waitForFunction(()=>Array.from(document.querySelectorAll('.domain-card[open] .previews img')).length===2&&Array.from(document.querySelectorAll('.domain-card[open] .previews img')).every(i=>i.complete&&i.naturalWidth===1280));
 await previews.screenshot({path:path.join(__dirname,'previews-live-desktop.png')});
 const img=previews.locator('a.preview-image-link').first();assert.equal(await img.getAttribute('target'),'_blank');
 const imgPopupPromise=p.waitForEvent('popup');await img.click();const ip=await imgPopupPromise;await ip.close();
 await p.click('#refresh');await p.waitForFunction(()=>!document.querySelector('#refresh').disabled);
 assert.equal(await p.inputValue('#search'),'black-robot.ro');assert(await card.getAttribute('open')!==null);
 await p.setViewportSize({width:393,height:852});await previews.scrollIntoViewIfNeeded();
 assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
 await previews.screenshot({path:path.join(__dirname,'previews-live-mobile.png')});
 await p.fill('#search','bonna.ro');card=p.locator('.domain-card[data-domain="bonna.ro"]');await card.locator('.chevron').click();
 assert((await card.locator('.preview-panel').first().textContent()).includes('Domeniul nu răspunde'));
 assert((await card.locator('.preview-panel').last().textContent()).includes('Copie locală'));
 const m=await (await c.request.get('https://wordpress.alba-vision.ro/_domain-previews.json')).json();
 const counts={};for(const v of Object.values(m.previews))counts[v.status]=(counts[v.status]||0)+1;
 assert.equal(errors.length,0,errors.join('\n'));
 for(const slug of ['bonna','cesiro','old-cesiro'])assert.equal((await c.request.get('https://wordpress.alba-vision.ro/'+slug+'/')).status(),200);
 const report={result:'PASS',tested_at:new Date().toISOString(),manifest_counts:counts,closed_image_requests:0,js_errors:errors};
 fs.writeFileSync(path.join(__dirname,'previews-live-report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report));await b.close();
})().catch(e=>{console.error(e);process.exit(1)});
